from __future__ import annotations

import datetime as _dt
import json
import os
import re
import string
import time
from typing import Any


def now_iso() -> str:
    return _dt.datetime.now(tz=_dt.timezone.utc).isoformat()


def monotonic_ns() -> int:
    return time.monotonic_ns()


def dumps_stable(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def to_printable(data: bytes) -> str:
    out: list[str] = []
    printable = set(string.printable)
    for b in data:
        ch = chr(b)
        if ch in printable and ch not in {"\x0b", "\x0c"}:
            out.append(ch)
        else:
            out.append(f"\\x{b:02x}")
    return "".join(out)


_ANSI_RE = re.compile(r"\x1B\[[0-9;?]*[A-Za-z]")
_OSC_RE = re.compile(r"\x1B\][^\x07]*(\x07|\x1B\\)")
_ESC_RE = re.compile(
    r"\x1b(?:"
    r"\[[0-?]*[ -/]*[@-~]"
    r"|\][^\x07]*\x07"
    r"|[@-Z\\-_]"
    r")"
)
_TRAILING_CONTINUATION_RE = re.compile(r"(?:\|\|?|\&\&)\s*$")


def clean_text(text: str) -> str:
    text = text.replace("\r\n", "\n").replace("\r", "")
    text = _ANSI_RE.sub("", text)
    text = _OSC_RE.sub("", text)

    out: list[str] = []
    for ch in text:
        if ch in ("\b", "\x7f"):
            if out:
                out.pop()
            continue
        if ch == "\a":
            continue
        out.append(ch)
    return "".join(out)


def strip_ansi(text: str) -> str:
    return _ESC_RE.sub("", text)


def shell_command_incomplete_reason(command: str) -> str | None:
    text = command.rstrip()
    if not text:
        return "EMPTY_COMMAND"
    if "\x00" in text:
        return "NUL_BYTE"

    in_single = False
    in_double = False
    in_backtick = False
    escaped = False

    for ch in text:
        if in_single:
            if ch == "'":
                in_single = False
            continue

        if in_double:
            if escaped:
                escaped = False
                continue
            if ch == "\\":
                escaped = True
                continue
            if ch == '"':
                in_double = False
            continue

        if in_backtick:
            if escaped:
                escaped = False
                continue
            if ch == "\\":
                escaped = True
                continue
            if ch == "`":
                in_backtick = False
            continue

        if ch == "'":
            in_single = True
            continue
        if ch == '"':
            in_double = True
            continue
        if ch == "`":
            in_backtick = True
            continue

    if in_single:
        return "UNBALANCED_SINGLE_QUOTE"
    if in_double:
        return "UNBALANCED_DOUBLE_QUOTE"
    if in_backtick:
        return "UNBALANCED_BACKTICK"

    if _TRAILING_CONTINUATION_RE.search(text):
        return "TRAILING_OPERATOR"

    stripped = text.rstrip()
    if stripped.endswith("\\"):
        slash_count = 0
        idx = len(stripped) - 1
        while idx >= 0 and stripped[idx] == "\\":
            slash_count += 1
            idx -= 1
        if slash_count % 2 == 1:
            return "TRAILING_BACKSLASH"

    return None

            "started_at": cap.started_at,
        }
        self._stop_capture_locked(session)
        return result

def log_status(self, selector: str) -> dict[str, Any]:
    with self._lock:
        session = self.get_session(selector)
        if session is None:
            return {"ok": False, "error_code": "SESSION_NOT_FOUND", "selector": selector}
        cap = session.active_capture
        if cap is None:
            return {"ok": True, "active": False, "session": session.to_public_dict()}
        return {
            "ok": True,
            "active": cap.status == "active",
            "capture_id": cap.capture_id,
            "log_path": cap.log_path,
            "line_count": cap.line_count,
            "byte_count": cap.byte_count,
            "started_at": cap.started_at,
            "session": session.to_public_dict(),
        }

# ── 檔案傳輸 ──────────────────────────────────────────────

def file_push(
    self,
    selector: str,
    *,
    local_path: str,
    remote_path: str,
    chunk_size: int = DEFAULT_CHUNK_SIZE,
    chunk_timeout_s: float | None = None,
    source: str = "agent",
) -> dict[str, Any]:
    """將 host 端檔案推送到 target。

    ``chunk_timeout_s``（#157）：單一 chunk 等待 target 回 prompt 的逾時；
    ``None`` 時沿用 ``profile.timeout_s``（夾 ``_MIN_FILE_CHUNK_TIMEOUT_S`` 地板），
    取代舊版寫死的 10.0s——bcm 類慢板已調大的 ``timeout_s`` 因此自動生效。
    """
    from .file_transfer import push_file

    suspend_human_interactive = False
    post = _PostCloseAction()
    busy_result: dict[str, Any] | None = None
    with self._lock:
        session = self.get_session(selector)
        if session is None or session.bridge is None or session.state != "READY":
            return {"ok": False, "error_code": "SESSION_NOT_READY"}
        # #139：同 execute_command 的第二層 gate——file 傳輸直寫 bridge、不經
        # execute_command，須各自補 gate（僅開始前擋；傳輸中 banner 到達不中途
        # abort，由傳輸自然 timeout，屬既有行為）。
        if not source.startswith("human:") and session.boot_quiet_active():
            return {"ok": False, "error_code": ERROR_AUTOBOOT_QUIET, "selector": session.profile.com}
        if session.recovering:
            return {"ok": False, "error_code": "SESSION_RECOVERING"}
        lease, post = self._refresh_interactive_locked(session)
        if lease is not None:
            if not source.startswith("human:") and lease.owner.startswith("human:"):
                suspend_human_interactive = True
            else:
                busy_result = {"ok": False, "error_code": "SESSION_INTERACTIVE_BUSY"}
        bridge = session.bridge
        prompt_regex = session.profile.prompt_regex
        profile_timeout_s = session.profile.timeout_s
        if busy_result is None:
            session.foreground_busy = True

    post.execute()
    if busy_result is not None:
        return busy_result
    effective_timeout_s = (
        chunk_timeout_s if chunk_timeout_s is not None
        else max(profile_timeout_s, _MIN_FILE_CHUNK_TIMEOUT_S)
    )
    if suspend_human_interactive:
        bridge.suspend_interactive()
    try:
        return push_file(
            bridge,
            local_path,
            remote_path,
            chunk_size=chunk_size,
            timeout_s=effective_timeout_s,
            prompt_regex=prompt_regex,
            source=source,
        )
    finally:
        with self._lock:
            session.foreground_busy = False
        if suspend_human_interactive:
            bridge.resume_interactive()

def file_pull(
    self,
    selector: str,
    *,
    remote_path: str,
    local_path: str | None = None,
    chunk_timeout_s: float | None = None,
    source: str = "agent",
) -> dict[str, Any]:
    """從 target 拉取檔案到 host。

    ``chunk_timeout_s``（#157）：整段 base64 讀取的逾時；``None`` 時沿用
    ``profile.timeout_s``（夾 ``_MIN_FILE_PULL_TIMEOUT_S`` 地板，維持舊版
    30.0s 行為基準），取代舊版寫死的 30.0s。
    """
    from .file_transfer import pull_file

    suspend_human_interactive = False
    post = _PostCloseAction()
    busy_result: dict[str, Any] | None = None
    with self._lock:
        session = self.get_session(selector)
        if session is None or session.bridge is None or session.state != "READY":
            return {"ok": False, "error_code": "SESSION_NOT_READY"}
        # #139：同 file_push 的 gate（pull 同樣直寫 bridge、不經 execute_command）。
        if not source.startswith("human:") and session.boot_quiet_active():
            return {"ok": False, "error_code": ERROR_AUTOBOOT_QUIET, "selector": session.profile.com}
        if session.recovering:
            return {"ok": False, "error_code": "SESSION_RECOVERING"}
        lease, post = self._refresh_interactive_locked(session)
        if lease is not None:
            if not source.startswith("human:") and lease.owner.startswith("human:"):
                suspend_human_interactive = True
            else:
                busy_result = {"ok": False, "error_code": "SESSION_INTERACTIVE_BUSY"}
        bridge = session.bridge
        prompt_regex = session.profile.prompt_regex
        profile_timeout_s = session.profile.timeout_s
        if busy_result is None:
            session.foreground_busy = True

    post.execute()
    if busy_result is not None:
        return busy_result
    effective_timeout_s = (
        chunk_timeout_s if chunk_timeout_s is not None
        else max(profile_timeout_s, _MIN_FILE_PULL_TIMEOUT_S)
    )
    if suspend_human_interactive:
        bridge.suspend_interactive()
    try:
        return pull_file(
            bridge,
            remote_path,
            local_path,
            timeout_s=effective_timeout_s,
            prompt_regex=prompt_regex,
            source=source,
        )
    finally:
        with self._lock:
            session.foreground_busy = False
        if suspend_human_interactive:
            bridge.resume_interactive()

        return {"ok": False, "error_code": "INVALID_ARGS"}
    return self._sessions.log_stop(selector)

if method == "session.log_status":
    selector = str(params.get("selector") or params.get("session_id") or params.get("com") or params.get("alias") or "")
    if not selector:
        return {"ok": False, "error_code": "INVALID_ARGS"}
    return self._sessions.log_status(selector)

if method == "file.push":
    selector = str(params.get("selector") or "")
    local_path = str(params.get("local_path") or "")
    remote_path = str(params.get("remote_path") or "")
    # 轉型全包 try（Copilot review）：非數字/空字串的 chunk_size／chunk_timeout_s
    # 不得讓 ValueError/TypeError 穿越 RPC 邊界；max(1, ...) 防 _split_chunks
    # 的 range(step=0)。
    try:
        chunk_size = max(1, int(params.get("chunk_size") or DEFAULT_CHUNK_SIZE))
        chunk_timeout_raw = params.get("chunk_timeout_s")
        chunk_timeout_s = (
            float(chunk_timeout_raw) if chunk_timeout_raw is not None else None
        )
    except (TypeError, ValueError):
        return {"ok": False, "error_code": "INVALID_ARGS"}
    source = str(params.get("source") or "agent")
    if not selector or not local_path or not remote_path:
        return {"ok": False, "error_code": "INVALID_ARGS"}
    session_id, err = self._resolve_session_id(selector, source=source)
    if err is not None:
        return err
    return self._sessions.file_push(
        selector,
        local_path=local_path,
        remote_path=remote_path,
        chunk_size=chunk_size,
        chunk_timeout_s=chunk_timeout_s,
        source=source,
    )

if method == "file.pull":
    selector = str(params.get("selector") or "")
    remote_path = str(params.get("remote_path") or "")
    local_path = params.get("local_path")
    try:  # 同 file.push：轉型例外不得穿越 RPC 邊界（Copilot review）
        chunk_timeout_raw = params.get("chunk_timeout_s")
        chunk_timeout_s = (
            float(chunk_timeout_raw) if chunk_timeout_raw is not None else None
        )
    except (TypeError, ValueError):
        return {"ok": False, "error_code": "INVALID_ARGS"}
    source = str(params.get("source") or "agent")
    if not selector or not remote_path:
        return {"ok": False, "error_code": "INVALID_ARGS"}
    session_id, err = self._resolve_session_id(selector, source=source)
    if err is not None:
        return err
    return self._sessions.file_pull(
        selector,
        remote_path=remote_path,
        local_path=str(local_path) if local_path else None,
        chunk_timeout_s=chunk_timeout_s,
        source=source,
    )

if method == "event.rule_set":
    try:
        rule = self._engine.rule_set(params or {})
        return {"ok": True, **dict(rule.raw)}
    except ValueError as e:
        return {"ok": False, "error_code": "INVALID_RULE_SCHEMA", "error": str(e)}

    # --from-seq 省略時不放 key → daemon 走 latest 模式（#124）；顯式帶值（含 0）→ range 模式。
    params = {"limit": args.limit}
    if args.from_seq is not None:
        params["from_seq"] = args.from_seq
    if selector:
        params["selector"] = selector
    if args.log_cmd == "tail-raw":
        return _run_rpc(args, "log.tail_raw", params)
    if args.log_cmd == "tail-text":
        return _run_rpc(args, "log.tail_text", params)

if args.cmd == "file":
    if args.file_cmd == "push":
        params = {
            "selector": args.selector,
            "local_path": args.local,
            "remote_path": args.remote,
            "chunk_size": args.chunk_size,
            "source": args.source,
        }
        # 不顯式帶就不佔 RPC payload 欄位——daemon 端走 profile timeout_s 推導（#157）
        if args.chunk_timeout_s is not None:
            params["chunk_timeout_s"] = args.chunk_timeout_s
        return _run_rpc(args, "file.push", params)
    if args.file_cmd == "pull":
        p: dict[str, Any] = {
            "selector": args.selector,
            "remote_path": args.remote,
            "source": args.source,
        }
        if args.local is not None:
            p["local_path"] = args.local
        if args.chunk_timeout_s is not None:
            p["chunk_timeout_s"] = args.chunk_timeout_s
        return _run_rpc(args, "file.pull", p)

if args.cmd == "wal" and args.wal_cmd == "export":
    return _run_rpc(args, "wal.range", {"from_seq": args.from_seq, "to_seq": args.to_seq, "limit": args.limit})

if args.cmd == "wal" and args.wal_cmd == "reset":
    return _run_rpc(args, "wal.reset", {})

if args.cmd == "wal" and args.wal_cmd == "current-seq":
    return _run_rpc(args, "wal.current_seq", {})

"""F7 檔案傳輸完整性（#21 #32）：binary round-trip md5 一致、不靜默截斷。

``serialwrap file push``／``file pull`` 走 base64 分段＋md5 校驗（見
``sw_core/file_transfer.py``，本檔僅唯讀 grep 鍵名，未 import）。已知缺口
（#123 defer，MINOR-5）：這兩個 RPC 方法**不在** CLI 的長操作白名單，未顯式
帶 ``--timeout`` 會沿用一般方法的 5.0s 預設，對多 chunk 的實際傳輸而言形同
必逾時──故本檔一律顯式帶較寬的 RPC ``--timeout``（global flag，需置於
``file`` 子命令**之前**）＋對應的 ``SwCli.run(timeout=...)``（subprocess 層
逾時，需 ≥ RPC timeout 加緩衝，否則會在 RPC 真正逾時前就被 Python 端
``subprocess.TimeoutExpired`` 打斷）。

timeout 估算基準（#157 修復後）：``DEFAULT_CHUNK_SIZE=512`` → 64KB≈129 chunks、
1MB=2048 chunks；以每 chunk 真實往返 0.1–0.3s 估，64KB≈13–39s、1MB≈205–614s，
timeout 取悲觀上界加緩衝，實際值待真機驗證校準。

已知殘留缺口（#157 範圍外）：``sw_core/uart_io.py`` 的 RX 視窗上限 131072 字元
（#158 改為絕對偏移記帳，但視窗仍有界、被修剪頭段永久丟失），``pull_file`` 不分段
一次讀全部——1MB 檔案 base64 輸出 ~1.4MB 遠超上限，``_SENTINEL_BEGIN`` 必被踢出
視窗 → ``PULL_PARSE_FAILED``。故 ``f7-larger-file-not-truncated`` 於 #157 修復後
push 端可成功，pull 端仍預期 SKIP（``transfer_environment_failure``）待 follow-up；
``f7-binary-roundtrip-md5``（64KB，base64 ~88.6KB 在上限內）應轉綠。
"""
from __future__ import annotations

import gzip
import hashlib
import os
from pathlib import Path
from typing import Any

from realhw.harness import CaseResult

from ..harness import Case, register


def _case(id, title, issues, hints=(), requires=(), destructive=False):
    def deco(fn):
        register(Case(id=id, family="F7", title=title, run=fn, issues=tuple(issues),
                      destructive=destructive, requires=tuple(requires), hints=tuple(hints)))
        return fn
    return deco


# push_file／pull_file（sw_core/file_transfer.py）在 target 缺 md5sum／base64
# 時的可觀測徵兆：md5sum 缺失 → _remote_md5 抓不到 32 hex → CHECKSUM_VERIFY_FAILED；
# base64 缺失 → sentinel 內夾帶的非 base64 內容解碼失敗 → BASE64_DECODE_FAILED。
_TOOL_MISSING_CODES = frozenset({"CHECKSUM_VERIFY_FAILED", "BASE64_DECODE_FAILED"})

# 逾時／連線層失敗徵兆：RPC 客戶端層的 TIMEOUT／SOCKET_ERROR／EMPTY_RESPONSE
# （sw_core/client.py），以及 file_transfer 內部逐段等待逾時的 TRANSFER_TIMEOUT／
# MOVE_TIMEOUT。這些代表傳輸「未完成」，非「完成但內容有誤」，故一律歸環境性。
_TIMEOUT_CODES = frozenset({
    "TIMEOUT", "SOCKET_ERROR", "EMPTY_RESPONSE", "TRANSFER_TIMEOUT", "MOVE_TIMEOUT",
})


def _probe_target_tools(ctx: Any, com: str) -> bool | None:
    """實測板端是否具備 base64＋md5sum：True＝都在、False＝缺、None＝探測本身失敗。

    區分 cg review 抓到的雙重含義：``CHECKSUM_VERIFY_FAILED``／``BASE64_DECODE_FAILED``
    既可能是板端缺工具（環境、SKIP），也可能是工具都在但傳輸真的壞掉（#32 類回歸、FAIL）。
    先探測工具存在性，後續判定才能分流。
    """
    # 用 which 而非 command -v（聚焦複驗實證：bcm 板 shell 無 `command` builtin，
    # `command -v` 回 'sh: command: not found' 被誤判成工具缺失）。busybox which 皆備。
    probe = ctx.sw.submit_and_wait(
        com, "which base64 >/dev/null 2>&1 && which md5sum >/dev/null 2>&1 && echo TOOLS_OK")
    ctx.note(f"{com}-tools-probe.json", str(probe))
    if probe.get("status") != "done":
        return None
    return "TOOLS_OK" in (probe.get("stdout") or "")


def _transfer_failure_verdict(resp: dict[str, Any], *, verb: str,
                              tools_present: bool | None) -> CaseResult:
    """push/pull 非 ok 的統一分流：逾時／連線層→環境 SKIP；工具徵兆碼→依探測結果分流
    （工具在＝#32 類真回歸 FAIL；工具不在或未知＝環境 SKIP）；其餘明確失敗→環境 SKIP。"""
    code = str(resp.get("error_code") or "unknown")
    if code in _TOOL_MISSING_CODES:
        if tools_present is True:
            return CaseResult(
                "FAIL",
                reason=f"{verb} 失敗（error_code={code}）且板端 base64/md5sum 皆在"
                       "——非工具缺失，屬傳輸損壞（#32 類回歸）",
                category="test", reason_code="binary_roundtrip_mismatch",
            )
        return CaseResult(
            "SKIP", reason=f"板端疑缺 base64／md5sum（error_code={code}，工具探測={tools_present}）",
            category="environment", reason_code="target_tool_missing",
        )
    return _environment_skip(resp, verb=verb)


def _environment_skip(resp: dict[str, Any], *, verb: str) -> CaseResult:
    """push/pull 未完成傳輸（逾時或其他明確失敗），非「完成但內容有誤」，判環境性 SKIP。"""
    code = str(resp.get("error_code") or "unknown")
    reason_code = "transfer_timeout" if code in _TIMEOUT_CODES else "transfer_environment_failure"
    return CaseResult(
        "SKIP",
        reason=f"{verb} 未完成（error_code={code}），視為環境因素而非程式回歸",
        category="environment",
        reason_code=reason_code,
    )


def _push(ctx: Any, com: str, local_path: Path, remote_path: str,
          *, rpc_timeout_s: float, proc_timeout_s: float) -> dict[str, Any]:
    return ctx.sw.run(
        "--timeout", str(rpc_timeout_s), "file", "push",
        "--selector", com, "--local", str(local_path), "--remote", remote_path,
        timeout=proc_timeout_s,
    )


def _pull(ctx: Any, com: str, remote_path: str, local_path: Path,
          *, rpc_timeout_s: float, proc_timeout_s: float) -> dict[str, Any]:
    return ctx.sw.run(
        "--timeout", str(rpc_timeout_s), "file", "pull",
        "--selector", com, "--remote", remote_path, "--local", str(local_path),
        timeout=proc_timeout_s,
    )


def _cleanup_remote(ctx: Any, com: str, remote_path: str) -> None:
    """收尾清板上暫存檔（case 執行期允許的寫操作）；盡力而為、失敗不影響已判定的 verdict。"""
    try:
        ctx.sw.submit_and_wait(com, f"rm -f {remote_path}")
    except Exception:
        pass


def _cleanup_local(*paths: Path) -> None:
    """收尾清本地暫存檔；盡力而為、失敗不影響已判定的 verdict。"""
    for p in paths:
        try:
            Path(p).unlink(missing_ok=True)
        except Exception:
            pass


def _binary_roundtrip_on(ctx, com):
    remote_path = "/tmp/swreg_rt.bin"
    ctx.case_dir.mkdir(parents=True, exist_ok=True)
    # gzip 壓縮亂數 bytes：header FLG 欄位恆為 0x00，實質保證含 null byte（#32 的
    # BASE64_DECODE_FAILED 類回歸正是在 payload 含 null byte 時才會現形）。
    payload = gzip.compress(os.urandom(64 * 1024))
    src_path = ctx.case_dir / "f7-rt-src.bin.gz"
    dst_path = ctx.case_dir / "f7-rt-dst.bin.gz"
    src_path.write_bytes(payload)
    try:
        tools_present = _probe_target_tools(ctx, com)
        if tools_present is False:
            return CaseResult("SKIP", reason="板端缺 base64／md5sum（探測確認）",
                              category="environment", reason_code="target_tool_missing")

        # chunk 512 下 64KB≈129 chunks（原 2048 時 33），timeout 同比放大（見 module docstring）
        push = _push(ctx, com, src_path, remote_path, rpc_timeout_s=180, proc_timeout_s=200)
        ctx.note(f"{com}-push.json", str(push))
        if not push.get("ok"):
            return _transfer_failure_verdict(push, verb="push", tools_present=tools_present)

        pull = _pull(ctx, com, remote_path, dst_path, rpc_timeout_s=180, proc_timeout_s=200)
        ctx.note(f"{com}-pull.json", str(pull))
        if not pull.get("ok"):
            return _transfer_failure_verdict(pull, verb="pull", tools_present=tools_present)

        md5_src = hashlib.md5(payload).hexdigest()
        md5_dst = hashlib.md5(dst_path.read_bytes()).hexdigest()
        if md5_src != md5_dst:
            return CaseResult(
                "FAIL", reason=f"round-trip md5 不一致：src={md5_src} dst={md5_dst}",
                category="test", reason_code="binary_roundtrip_mismatch")
        return CaseResult("PASS")
    finally:
        _cleanup_remote(ctx, com, remote_path)
        _cleanup_local(src_path, dst_path)


def _larger_file_on(ctx, com):
    remote_path = "/tmp/swreg_big.bin"
    ctx.case_dir.mkdir(parents=True, exist_ok=True)
    payload = os.urandom(1024 * 1024)
    src_path = ctx.case_dir / "f7-big-src.bin"
    dst_path = ctx.case_dir / "f7-big-dst.bin"
    src_path.write_bytes(payload)
    try:
        tools_present = _probe_target_tools(ctx, com)
        if tools_present is False:
            return CaseResult("SKIP", reason="板端缺 base64／md5sum（探測確認）",
                              category="environment", reason_code="target_tool_missing")

        # chunk 512 下 1MB=2048 chunks，悲觀估 205–614s（見 module docstring）；取 640 上界。
        # 註：pull 端在 RX 視窗 128KiB 上限修復前仍預期 PULL_PARSE_FAILED → SKIP。
        push = _push(ctx, com, src_path, remote_path, rpc_timeout_s=640, proc_timeout_s=660)
        ctx.note(f"{com}-push.json", str(push))
        if not push.get("ok"):
            return _transfer_failure_verdict(push, verb="push", tools_present=tools_present)

        pull = _pull(ctx, com, remote_path, dst_path, rpc_timeout_s=640, proc_timeout_s=660)
        ctx.note(f"{com}-pull.json", str(pull))
        if not pull.get("ok"):
            return _transfer_failure_verdict(pull, verb="pull", tools_present=tools_present)

        # push/pull 皆回報成功，才是這個 case 真正要抓的回歸：內容是否被靜默截斷。
        dst_bytes = dst_path.read_bytes()
        if len(dst_bytes) != len(payload):
            return CaseResult(
                "FAIL",
                reason=f"檔案大小不符（疑似截斷）：src={len(payload)} dst={len(dst_bytes)}",
                category="test", reason_code="transfer_truncated")
        md5_src = hashlib.md5(payload).hexdigest()
        md5_dst = hashlib.md5(dst_bytes).hexdigest()
        if md5_src != md5_dst:
            return CaseResult(
                "FAIL", reason=f"1MB round-trip md5 不一致：src={md5_src} dst={md5_dst}",
                category="test", reason_code="transfer_truncated")
        return CaseResult("PASS")
    finally:
        _cleanup_remote(ctx, com, remote_path)
        _cleanup_local(src_path, dst_path)


_ENV_SKIP_CODES = frozenset({
    "transfer_timeout", "transfer_environment_failure", "target_tool_missing"})


def _run_on_boards(ctx, runner, *, case_tag: str):
    """逐板嘗試（首輪批次驗收調校，#157）：COM0（prpl 無顯式 timeout_s、且真機實測
    存在無流控節流掉字的傳輸層限制）環境性失敗時改試 COM1（bcm 有 timeout_s 配置、
    可實證 #157 chunk/timeout 機制）。第一個決定性結果（PASS 或 test-FAIL）即回傳；
    全數環境性 SKIP 才 SKIP（彙整逐板 reason）。"""
    outcomes = []
    for board in ctx.cfg.get("boards") or []:
        com = str(board["com"])
        r = runner(ctx, com)
        outcomes.append(f"{com}: {r.verdict}/{r.reason_code or '-'}")
        if not (r.verdict == "SKIP" and (r.reason_code or "") in _ENV_SKIP_CODES):
            r.reason = f"[{com}] {r.reason}" if r.reason else f"[{com}]"
            return r
    ctx.note(f"{case_tag}-board-outcomes.txt", "\n".join(outcomes))
    return CaseResult(
        "SKIP",
        reason="全部板卡皆環境性失敗：" + "；".join(outcomes),
        category="environment", reason_code="transfer_env_all_boards",
    )


@_case("f7-binary-roundtrip-md5", "binary round-trip md5 一致（含 null byte）",
       issues=("#32", "#21"),
       hints=("逐板嘗試：prpl 板受無流控節流限制（#157 後續 issue 追蹤），bcm 板"
              "（timeout_s 配置齊）為 #157 機制的實證面。",))
def f7_binary_roundtrip_md5(ctx):
    return _run_on_boards(ctx, _binary_roundtrip_on, case_tag="rt")


@_case("f7-larger-file-not-truncated", "1MB 檔案 push→pull 不靜默截斷", issues=("#21",),
       hints=("逐板嘗試（同 f7-binary-roundtrip-md5）。",))
def f7_larger_file_not_truncated(ctx):
    return _run_on_boards(ctx, _larger_file_on, case_tag="big")

